<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('employees.manage');verify_csrf();$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['work_email']??'')));$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10){flash('error','Name, valid email, and a password of at least 10 characters are required.');redirect('employees.php');}try{transaction(function(PDO $pdo)use($name,$email,$password){$pdo->prepare('INSERT INTO users(email,password_hash,account_status) VALUES(?,? ,"active")')->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$code='EMP-'.str_pad((string)$uid,4,'0',STR_PAD_LEFT);$dept=(int)($_POST['department_id']??0)?:null;$pdo->prepare('INSERT INTO employees(user_id,employee_code,full_name,work_email,contact_number,department_id,job_title,employment_status,joining_date) VALUES(?,?,?,?,?,?,?,"active",?)')->execute([$uid,$code,$name,$email,trim((string)($_POST['contact_number']??''))?:null,$dept,trim((string)($_POST['job_title']??''))?:null,$_POST['joining_date']?:null]);$eid=(int)$pdo->lastInsertId();$role=(int)($_POST['role_id']??0);if($role)$pdo->prepare('INSERT INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$uid,$role]);audit('employee.created','employee',$eid,['email'=>$email]);});flash('success','Employee account created.');}catch(Throwable $e){flash('error','Could not create employee. The email may already exist.');}redirect('employees.php');
